// Accepts 1/0, true/false, "on"/"off" or an object with .state -
// depending on what the virtual switch delivers.
var p = msg.payload;
if (p !== null && typeof p === 'object') {
    p = (p.state !== undefined) ? p.state : p.value;
}
var on = (p === 1 || p === true || p === '1' || p === 'on');
var value = on ? 1 : 0;

// The settings value, not the device path /Mode!
msg.payload = 'dbus -y com.victronenergy.settings'
    + ' /Settings/Devices/tsbuckboost/SeparateTempSensors SetValue ' + value
    + ' && svc -t /service/TsBuckBoost';
msg.tsbbValue = value;
return msg;

// Wired to the third exec output: the return code. It fires exactly once
// per run, unlike stdout/stderr.
var rc = (msg.payload !== null && typeof msg.payload === 'object'
          && msg.payload.code !== undefined) ? msg.payload.code : 0;
var state = msg.tsbbValue === 1 ? 'on' : 'off';

if (rc === 0) {
    msg.payload = 'separate temperature devices ' + state
        + ', driver restarting';
} else {
    msg.payload = 'failed (exit code ' + rc + ') - is Node-RED allowed to run'
        + ' commands on the GX device?';
}
return msg;
